package com.quincaisoft.finance.application;
import com.quincaisoft.finance.api.FinanceBootstrapService;import com.quincaisoft.finance.infrastructure.*;import com.quincaisoft.shared.BootstrapScope;import jakarta.persistence.*;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.*;import java.util.*;import java.time.*;
@Service public class DefaultFinanceBootstrapService implements FinanceBootstrapService { private final EntityManager em; public DefaultFinanceBootstrapService(EntityManager em){this.em=em;}
@Transactional(propagation=Propagation.MANDATORY) public void initialize(BootstrapScope s,UUID periodId,LocalDate businessDate) {require(s);var p=new FinancialPeriodEntity();p.tenantId=s.tenantId();p.companyId=s.companyId();p.id=periodId;p.startDate=businessDate.withDayOfYear(1);p.endDate=businessDate.withMonth(12).withDayOfMonth(31);p.status="Open";p.version=0;em.persist(p);for(String code:FinanceBootstrapService.OPERATIONAL_ACCOUNTS){var m=new BootstrapChartMapping();m.tenantId=s.tenantId();m.companyId=s.companyId();m.operationalCode=code;m.reviewStatus="PROVISIONAL";em.persist(m);}em.flush();}
private void require(BootstrapScope s) { if(!em.isJoinedToTransaction()) throw new IllegalStateException("Bootstrap must join platform transaction"); Number n=(Number)em.createNativeQuery(BootstrapScope.AUTHORIZATION_SQL).setParameter("p",s.provisioningId()).setParameter("t",s.tenantId()).setParameter("c",s.companyId()).setParameter("b",s.branchId()).setParameter("o",s.ownerId()).getSingleResult(); if(n.longValue()!=1)throw new org.springframework.security.access.AccessDeniedException("Approved current platform bootstrap required"); }
}
